case 'pagos':titulo('REGISTRO INTERNO','Cada importe, en su lugar.','Pagos, reembolsos y comprobantes académicos.');?><div class="table-wrap"><table><thead><tr><th>Comprobante</th><th>Operación</th><th>Monto</th><th>Estado</th><th>Fecha</th></tr></thead><tbody><?php foreach(filas('SELECT p.*,r.id recibo FROM rf_payments p JOIN rf_receipts r ON r.pago_id=p.id ORDER BY p.id DESC') as $pay):$t=$pay['reparacion_id']?'reparacion':($pay['pedido_id']?'pedido':($pay['suscripcion_id']?'suscripcion':'oferta'));$rid=$pay[$t==='reparacion'?'reparacion_id':($t==='pedido'?'pedido_id':($t==='suscripcion'?'suscripcion_id':'oferta_id'))];?><tr><td><a class="text-link" href="<?=e(ruta('comprobante',['id'=>$pay['recibo']]))?>">RC-<?=str_pad($pay['recibo'],5,'0',STR_PAD_LEFT)?> ↗</a></td><td><?=e(folio($t,(int)$rid))?></td><td><?=dinero($pay['total'])?></td><td><?=badge($pay['estado'])?></td><td><?=e($pay['creado'])?></td></tr><?php endforeach;?></tbody></table></div><?php break;
case 'comprobante':$rid=(int)($_GET['id']??0);$pay=fila('SELECT p.*,r.id recibo,r.creado emitido FROM rf_receipts r JOIN rf_payments p ON p.id=r.pago_id WHERE r.id=?',[$rid]);exigir((bool)$pay,'Comprobante no disponible.');$tipo=$pay['reparacion_id']?'reparacion':($pay['pedido_id']?'pedido':($pay['suscripcion_id']?'suscripcion':'oferta'));$id=(int)$pay[$tipo==='reparacion'?'reparacion_id':($tipo==='pedido'?'pedido_id':($tipo==='suscripcion'?'suscripcion_id':'oferta_id'))];$op=operativo($tipo,$id);$client=fila('SELECT nombre,correo FROM rf_users WHERE id=?',[$op['cliente_id']]);?>
<section class="receipt card"><div class="section-title"><span class="brand">RetroFix</span><span class="eyebrow">COMPROBANTE INTERNO</span></div><h1>RC-<?=str_pad((string)$rid,5,'0',STR_PAD_LEFT)?></h1><p class="alert info">Pago simulado · Documento académico no fiscal · No acredita un cobro real.</p><div class="facts"><div>Cliente<strong><?=e($client['nombre'])?></strong></div><div>Operación<strong><?=e(folio($tipo,$id))?></strong></div><div>Fecha<strong><?=e($pay['emitido'])?></strong></div><div>Método<strong><?=e($pay['metodo'])?></strong></div><div>Referencia<strong><?=e($pay['referencia'])?></strong></div><div>Estado<strong><?=e(etiqueta($pay['estado']))?></strong></div></div><?php if($tipo==='reparacion'):$quote=cotizacion($id);if($quote):?><div class="fact-row"><span>Mano de obra</span><strong><?=dinero($quote['mano_obra'])?></strong></div><div class="fact-row"><span>Refacciones</span><strong><?=dinero($quote['refacciones'])?></strong></div><?php endif;endif;?><div class="receipt-total"><span><?=$tipo==='oferta'?'Pago al vendedor':'Total registrado'?></span><strong><?=dinero($pay['total'])?></strong></div><div class="actions no-print"><button class="button" type="button" data-print>Imprimir / guardar PDF</button><?=boton('Ver operación',ruta('detalle',['tipo'=>$tipo,'id'=>$id]),'ghost')?></div></section>
<?php break;case 'auditoria':titulo('TRAZABILIDAD','Cada acción deja huella.','Fecha, responsable y operación. No se registran contraseñas.');?><div class="table-wrap"><table><thead><tr><th>Fecha</th><th>Autor</th><th>Operación</th><th>Acción</th><th>Detalle</th></tr></thead><tbody><?php foreach(filas('SELECT a.*,u.nombre FROM rf_audit a JOIN rf_users u ON u.id=a.autor_id ORDER BY a.id DESC LIMIT 200') as $a):?><tr><td><?=e($a['creado'])?></td><td><?=e($a['nombre'])?></td><td><?=e($a['tipo'].' #'.$a['referencia_id'])?></td><td><?=e($a['accion'])?></td><td><?=e($a['detalle'])?></td></tr><?php endforeach;?></tbody></table></div><?php break;endswitch;?>
